// 4. CASO ESPECIAL: Solicitud de Demo / Prueba Gratis
} else if (normalized.includes("demo") || normalized.includes("prueba") || normalized.includes("test") || normalized.includes("probar") || normalized.includes("gratis") || normalized.includes("cortesia")) {
