  }

// 6. CASO ESPECIAL: Consulta de Precios, Tarifas o Planes
} else if (normalized.includes("precio") || normalized.includes("costo") || normalized.includes("cuanto vale") || normalized.includes("cuanto cuesta") || normalized.includes("tarifa") || normalized.includes("planes") || normalized.includes("valores") || normalized.includes("euro")) {
