  ].join("\n");

// 8. RESPUESTA DE BIENVENIDA Y ATENCION CONCIERGE NATURAL
} else {
  if (isSpain) {
    responseText = "✦ *VIDEM | Private Tech Concierge Europa* 🎬🇪🇸\n\n¡Hola " + senderName + "! Qué tal. Te damos la bienvenida a *VIDEM*.\n\nBrindamos consultoría y enrutamiento privado de streaming para que disfrutes de películas y series en calidad de cine original (*4K Remux a 80 Mbps con Dolby Vision y Dolby Atmos sin pérdidas*) directamente en tu Smart TV o Fire TV en tu salón, sin compresión y sin pagar 5 suscripciones.\n\nCuéntame, ¿qué modelo de televisor o equipo de sonido tienes en tu salón, o cómo te podemos ayudar hoy?";
