};

// FILTRO DE ALERTAS EN TIEMPO REAL PARA CAMILO
// Se ejecuta si hay solicitud de asesor humano, codigo TV, lead Laneros o pago verificado
const item = $input.item.json;

if (!item.adminAlertText) {
  return []; // No requiere alerta
}

return {
  adminNumber: "573103311543",
  adminText: item.adminAlertText
};

// FILTRO: Si responseText está vacío o es cliente VIP en silencio, NO enviar nada al cliente
const item = $input.item.json;
if (!item.responseText || item.isVipSilent) {
  return []; // Detiene el envío hacia el WhatsApp del cliente
}
return item;
